// Deterministic, local-only review fixtures. No API, storage or production code.
(() => {
'use strict';
const states=['team-readiness','roster-empty','roster-incomplete','roster-complete','roster-full','roster-above-maximum','add-existing','add-new','add-duplicate','adding','add-failed','remove','possible-duplicate-member','history-expanded','cancelled-read-only','awaiting-terms','conflict','loading','failed'];
const query=new URLSearchParams(location.search);
const state=states.includes(query.get('state'))?query.get('state'):'team-readiness';
document.body.dataset.state=state;
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(type='info')=>`<svg class="fl-icon" viewBox="0 0 24 24" aria-hidden="true">${({info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',error:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 3v1"/>',down:'<path d="m7 10 5 5 5-5"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',switch:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>'})[type]}</svg>`;
const button=(label,action='',cls='',attrs='')=>`<button type="button" class="${cls}" ${action?`data-action="${action}"`:''} ${attrs}>${label}</button>`;
const notice=(heading,text,tone='info',extra='')=>`<section class="fl-notice ${tone}" role="${tone==='danger'?'alert':'status'}">${icon(tone==='danger'?'error':'info')}<div><strong>${heading}</strong><p>${text}</p>${extra}</div></section>`;
const players=['Robin Vale','Sam Reed','Jamie Brook','Taylor Finch','Casey Wood','Drew Hill'];
const count=({'roster-empty':0,'roster-complete':4,'roster-full':5,'roster-above-maximum':6,'history-expanded':3,'cancelled-read-only':3})[state]??2;
let members=players.slice(0,count), team=state==='cancelled-read-only'?'Harbour Lights':'River Falcons', mode=state, busy=['adding','remove'].includes(state), opener=null;
let addedName='Reese Moss';
const stamp=i=>`11 November 2026, 18:${20+i*2}`;
const addedTimes=new Map(players.map((name,i)=>[name,stamp(i)]));
let history=members.map((name,i)=>({name,verb:'Added',at:stamp(i)}));
if(state==='history-expanded')history=[{name:'Parker Snow',verb:'Added',at:'11 November 2026, 18:10'},{name:'Parker Snow',verb:'Removed',at:'11 November 2026, 18:15'},...history];
const readiness=n=>`${n} of 3–5 players${n<3?' · incomplete':n>5?' · above maximum':''}`;
const readinessMarkup=(n,awaiting=false)=>`<p class="readiness ${n<3?'incomplete':n>5?'above':''}">${awaiting?"Waiting for the tournament's roster sizes":readiness(n)}</p>`;
function teamRow(name,n,waiting=false,cancelled=false){
 return `<li><div><div class="team-identity"><h3>${waiting?'1. ':''}${name}</h3><div data-team-readiness="${name}">${readinessMarkup(n,state==='awaiting-terms')}</div></div><p class="help">${cancelled?'Cancelled · 11 November 2026, 18:35 · Alex Morgan':waiting?'Admission pending · Waiting since 11 November 2026, 18:00 · Europe/Madrid':'Admitted'}</p></div><div class="row-actions">${button('Roster','roster','',`data-team="${name}" data-count="${n}" aria-label="Roster: ${name}"`)}${cancelled?'':(waiting?button('Admit','explain','','aria-label="Admit: Meadow Foxes"'):'')+button('Cancel entry','explain','',`aria-label="Cancel entry: ${name}"`)}</div></li>`;
}
const labels='<div class="labels" aria-label="Tournament lifecycle"><span>Published</span><span>Registration open</span><span>Preparing</span></div>';
document.querySelector('#state-links').innerHTML=states.map(key=>`<a href="?state=${key}" ${key===state?'aria-current="page"':''}>${key.replaceAll('-',' ')}</a>`).join('');
document.querySelector('#surface').innerHTML=`<div class="fl-shell"><aside class="fl-rail"><a class="brand" href="access-states.html?state=one-organisation">HERALD<span>.</span></a><div class="fl-context"><strong>Northside Gaming</strong><small>Organisation · Owner</small><a href="access-states.html?state=organisation-selector">${icon('switch')}Switch organisation</a></div><nav class="fl-nav" aria-label="Workspace"><a href="access-states.html?state=one-organisation">Overview</a><a href="entries-states.html?state=list-with-entries&kind=team" aria-current="page">Tournaments</a></nav></aside><main id="main" class="fl-page" tabindex="-1"><header class="fl-top"><span>Organiser workspace</span><div class="fl-account">${button('Alex Morgan'+icon('down'),'account','','aria-expanded="false" aria-controls="account-panel"')}<div id="account-panel" class="fl-account-panel" hidden><strong>Alex Morgan</strong><small>Signed in with your account provider</small><a class="button" href="access-states.html?state=one-organisation">Organise</a>${button('Sign out','explain')}</div></div></header><div class="fl-content"><header class="fl-heading"><a class="back" href="entries-states.html?state=fields-locked&kind=team">Back to configuration</a><div class="title"><h1>Entries · Saturday Team League</h1>${labels}</div><p class="lead">Example strategy · Standard variant · Team · Madrid</p><p class="lead">28 November 2026, 10:00 · Europe/Madrid</p></header><div class="column"><section class="fl-summary" aria-labelledby="summary-heading"><div><h2 id="summary-heading">3 of 4 teams</h2><p class="help">Manual admission · 1 pending your decision</p><p class="help">Entry terms updated 11 November 2026, 18:00 · Europe/Madrid</p></div>${button('Add team','explain','primary')}</section><section class="fl-group"><h2>Admitted · 3</h2><ul class="fl-rows">${teamRow('Team A',4)}${teamRow('River Falcons',state==='team-readiness'?2:count)}${teamRow('Cedar Owls',6)}</ul></section><section class="fl-group"><h2>Waiting · 1</h2><ol class="fl-rows">${teamRow('Meadow Foxes',4,true)}</ol></section><details class="fl-history" id="cancelled"><summary>Cancelled · 1</summary><ul class="fl-rows">${teamRow('Harbour Lights',3,false,true)}</ul></details></div></div></main></div>`;
function updateRow(){document.querySelector(`[data-team="${team}"]`).dataset.count=members.length;document.querySelector(`[data-team-readiness="${team}"]`).innerHTML=readinessMarkup(members.length,state==='awaiting-terms');}
function historyMarkup(){return `<details class="fl-history" ${mode==='history-expanded'?'open':''}><summary>History · ${history.length}</summary><ul>${history.map(item=>`<li>${item.verb} ${escape(item.name)}<small>Alex Morgan · ${item.at} · Europe/Madrid</small></li>`).join('')||'<li>No roster changes yet.</li>'}</ul></details>`;}
function addForm(){
 const search=mode==='add-existing',duplicate=mode==='add-duplicate',failed=mode==='add-failed';
 const value=search?'R':duplicate?'rowan lake':addedName;
 const result=(name,onTeam=false)=>`<li><div><h3>${name}</h3><p class="help">Existing player · created 10 November 2026</p>${onTeam?'<p class="help">On Team A</p>':''}</div>${onTeam?'':button('Add player','add-result','primary',`data-name="${name}"`)}</li>`;
 return `<section class="column" aria-labelledby="add-heading"><h3 id="add-heading">Add player</h3><p class="help">Choose a guest player of Northside Gaming or create a new player.</p><div class="actions choices">${button('Choose existing','choose-existing','',`aria-pressed="${search}" ${busy?'disabled':''}`)}${button('Create new','choose-new','',`aria-pressed="${!search}" ${busy?'disabled':''}`)}</div><form class="column" id="add-form"><div class="fl-field"><label for="player-name">${search?'Search by name':'Name (alias)'}</label><input id="player-name" name="name" maxlength="80" value="${escape(value)}" ${busy?'readonly':''} aria-describedby="player-name-help"><p class="help" id="player-name-help">${search?'Only player guests in Northside Gaming.':'1–80 characters after trimming. Review the name before creating the guest.'}</p></div>${failed?notice('Player was not added','The request failed. Nothing was added. Your input is kept; try again.','danger'):''}${duplicate?notice('Possible duplicate','These player guests have the same name ignoring case, accents and spaces. Choose one or create a separate guest. Nothing will be merged.'):''}${search||duplicate?`<ul class="fl-rows">${result(search?'Reese Moss':'Rowan Lake',!search)}${search?result('Rowan Lake',true):''}</ul>`:''}${busy?'<p class="help" role="status">Adding player. Please wait; do not submit again.</p>':''}<div class="actions">${search?'':button(busy?'Adding…':duplicate?'Create a new player anyway':failed?'Retry add':'Create and add player','create',duplicate?'':'primary',busy?'disabled':'')}${button('Back to roster','back','',busy?'disabled':'')}</div></form></section>`;
}
function contents(){
 const readonly=team==='Harbour Lights',awaiting=state==='awaiting-terms';
 const head=`<h2 id="roster-heading" tabindex="-1" class="focus-evidence">Roster · ${team}</h2><div class="column"><p class="help">${readonly?'Cancelled team · Read-only':team==='Meadow Foxes'?'Waiting · Admission pending':'Admitted team'} · Saturday Team League</p><p class="help">${awaiting?'Roster sizes not available':'3 to 5 players'} · Europe/Madrid</p>`;
 const close=`<div class="actions">${button('Back to entries','close','',busy?'disabled':'')}</div></div>`;
 if(mode==='loading')return head+'<section role="status" aria-busy="true"><h3>Loading roster…</h3><p>Please wait while the team’s roster is loaded.</p></section>'+close;
 if(mode==='failed')return head+notice('Roster could not be loaded','No members are shown. Try loading the roster again.','danger',`<div class="actions">${button('Try again','reload','primary')}</div>`)+close;
 const ready=readinessMarkup(members.length,awaiting);
 if(mode.startsWith('add-')||mode==='adding')return head+ready+addForm()+close;
 const blocked=members.length>=5||awaiting;
 const why=awaiting?"Waiting for the tournament's roster sizes":members.length>5?'The maximum was lowered. Remove members until the roster is below 5 players before adding.':'The roster has 5 players, the maximum. Remove a member before adding another player.';
 return head+ready+(readonly?notice('Read-only roster','This team’s entry is cancelled. Its roster is kept as evidence and cannot be changed.'):mode==='conflict'?notice('This roster changed elsewhere','Nothing changed with this request. Reload the latest roster before trying again.','danger',`<div class="actions">${button('Reload latest','reload')}</div>`):'')+`<section class="column" aria-labelledby="members-heading"><h3 id="members-heading">Members · ${members.length}</h3>${members.length?`<ul class="fl-rows member-list">${members.map((name,i)=>`<li><div><h3>${escape(name)}</h3><p class="help">Added ${addedTimes.get(name)||stamp(i)}</p>${mode==='possible-duplicate-member'&&i===0?notice('Possible duplicate of a player on Team A','Different guest players share this name. Review their identities; neither player is blocked.'):''}</div>${readonly?'':button(mode==='remove'&&i===0?'Removing…':'Remove','remove-member','',`data-index="${i}" aria-label="${mode==='remove'&&i===0?'Removing':'Remove'} ${escape(name)}" ${busy||awaiting||mode==='conflict'?'disabled':''}`)}</li>`).join('')}</ul>`:'<p class="help">No players yet. Add players to build this team’s tournament roster.</p>'}${mode==='remove'?'<p class="help" role="status">Removing Robin Vale. Please wait; do not submit again.</p>':''}${readonly?'':`<div>${button('Add player','add','primary',blocked||busy||mode==='conflict'?`disabled ${blocked?'aria-describedby="add-reason"':''}`:'')}${blocked?`<p class="help" id="add-reason">${why}</p>`:''}</div>`}</section>`+historyMarkup()+close;
}
function renderDrawer(focus=true){const d=document.querySelector('#roster-drawer');d.innerHTML=contents();d.setAttribute('aria-busy',String(busy));if(focus)d.querySelector('#roster-heading').focus();}
function openDrawer(trigger){
 opener=trigger||document.querySelector('[data-team="River Falcons"]');
 const d=document.createElement('dialog');d.id='roster-drawer';d.className='fl-modal drawer';d.setAttribute('aria-labelledby','roster-heading');document.body.append(d);
 document.body.style.setProperty('--review-height',document.querySelector('.review-bar').getBoundingClientRect().height+'px');document.body.classList.add('has-modal');renderDrawer(false);d.showModal();d.querySelector('#roster-heading').focus();
 d.addEventListener('cancel',e=>{e.preventDefault();if(!busy)closeDrawer();});
 d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(!busy)closeDrawer();return;}if(e.key!=='Tab')return;const controls=[...d.querySelectorAll('button:not(:disabled),input:not(:disabled),summary')].filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.id==='roster-heading')){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
}
function closeDrawer(){document.querySelector('#roster-drawer')?.remove();document.body.classList.remove('has-modal');opener?.focus();}
function addMember(name){if(!name.trim()||members.length>=5||busy)return;if(!members.includes(name)){members.push(name);addedTimes.set(name,'11 November 2026, 18:40');history.push({name,verb:'Added',at:'11 November 2026, 18:40'});}mode='roster-complete';updateRow();renderDrawer();}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog')){const panel=document.querySelector('#account-panel');if(!panel.hidden){panel.hidden=true;const toggle=document.querySelector('[data-action="account"]');toggle.setAttribute('aria-expanded','false');toggle.focus();}}});
document.addEventListener('submit',e=>{e.preventDefault();if(!busy)addMember(document.querySelector('#player-name')?.value||'');});
document.addEventListener('click',e=>{
 const control=e.target.closest('[data-action]');if(!control||control.disabled)return;const action=control.dataset.action;
 if(action==='account'){const panel=document.querySelector('#account-panel');panel.hidden=!panel.hidden;control.setAttribute('aria-expanded',String(!panel.hidden));return;}
 if(action==='explain'){document.querySelector('#prototype-explanation')?.remove();const p=document.createElement('p');p.id='prototype-explanation';p.className='help';p.setAttribute('role','status');p.textContent='This action belongs to the existing entries prototype. No request is sent from this roster review.';control.parentElement.append(p);return;}
 if(action==='roster'){team=control.dataset.team;members=(team==='Team A'?['Rowan Lake','Ellis Stone','Quinn Ash','Avery Lane']:players).slice(0,Number(control.dataset.count));history=members.map((name,i)=>({name,verb:'Added',at:stamp(i)}));mode=team==='Harbour Lights'?'cancelled-read-only':'roster-complete';busy=false;openDrawer(control);return;}
 if(busy)return;
 if(action==='close'){closeDrawer();return;}
 if(action==='add'||action==='choose-existing'){mode='add-existing';renderDrawer();return;}
 if(action==='choose-new'){mode='add-new';renderDrawer();return;}
 if(action==='back'){mode='roster-complete';renderDrawer();return;}
 if(action==='create'){addMember(document.querySelector('#player-name').value);return;}
 if(action==='add-result'){addMember(control.dataset.name);return;}
 if(action==='remove-member'){const name=members.splice(Number(control.dataset.index),1)[0];history.push({name,verb:'Removed',at:'11 November 2026, 18:42'});mode='roster-complete';updateRow();renderDrawer();return;}
 if(action==='reload'){mode='roster-complete';if(state==='conflict')members=members.slice(1);updateRow();renderDrawer();}
});
if(state!=='team-readiness')openDrawer();
})();
